-- Control library (FRA control map). Generated — do not edit by hand.
INSERT INTO rc_controls (control_code, area, title_en, title_ar, requirement_en, control_type, type_codes, frequency, criticality, owner_role, linked_module, linked_params, licence_types, test_procedure_en) VALUES ('FRA-001', 'capital_licensing', 'Paid-up capital at or above the licence minimum', 'رأس المال المدفوع لا يقل عن الحد الأدنى للترخيص', 'Capital register (authorised/issued/paid/registered, by date) is compared with the minimum per licence type; red if below; days to deadline shown.', 'automated', 'A/M', 'monthly', 'critical', 'cfo', 'prudential', ARRAY['capital.min_paid_up']::text[], ARRAY['all']::text[], 'Confirm that: capital register (authorised/issued/paid/registered, by date) is compared with the minimum per licence type; red if below; days to deadline shown.') ON CONFLICT (control_code) DO NOTHING;
