INSERT INTO rc_controls (control_code, area, title_en, title_ar, requirement_en, control_type, type_codes, frequency, criticality, owner_role, linked_module, linked_params, licence_types, test_procedure_en) VALUES ('FRA-003', 'capital_licensing', 'Solvency standards met (equity, leverage, capital base)', 'الالتزام بمعايير الملاءة (حقوق الملكية والرافعة وقاعدة رأس المال)', 'Quarterly solvency calculation from financial data input/import; negative equity is critical; trend over time.', 'automated', 'A/M', 'quarterly', 'critical', 'cfo', 'prudential', ARRAY['solvency.max_leverage_ratio', 'solvency.min_equity']::text[], ARRAY['all']::text[], 'Confirm that: quarterly solvency calculation from financial data input/import; negative equity is critical; trend over time.') ON CONFLICT (control_code) DO NOTHING;
INSERT INTO rc_controls (control_code, area, title_en, title_ar, requirement_en, control_type, type_codes, frequency, criticality, owner_role, linked_module, linked_params, licence_types, test_procedure_en) VALUES ('FRA-004', 'capital_licensing', 'Clients within the licensed activity scope', 'العملاء في نطاق النشاط المرخص به', 'Eligibility rule at origination and on portfolio import: client monthly revenue / project size vs the licence ceiling; a breach blocks the loan or needs an approved exception.', 'automated', 'A', 'daily', 'high', 'credit_head', 'lending', ARRAY['lending.max_client_monthly_revenue', 'lending.max_project_size']::text[], ARRAY['microfinance', 'consumer_finance']::text[], 'Confirm that: eligibility rule at origination and on portfolio import: client monthly revenue / project size vs the licence ceiling; a breach blocks the loan or needs an approved exception.') ON CONFLICT (control_code) DO NOTHING;
INSERT INTO rc_controls (control_code, area, title_en, title_ar, requirement_en, control_type, type_codes, frequency, criticality, owner_role, linked_module, linked_params, licence_types, test_procedure_en) VALUES ('FRA-005', 'capital_licensing', 'Consistent registered address on official documents', 'توحيد العنوان المسجل في المستندات الرسمية', 'Corporate profile is the single source of truth for the registered address; templates use it; uploaded board minutes/letters whose address differs are flagged.', 'automated', 'A/E', 'quarterly', 'medium', 'board_secretary', 'governance', '{}'::text[], ARRAY['all']::text[], 'Confirm that: corporate profile is the single source of truth for the registered address; templates use it; uploaded board minutes/letters whose address differs are flagged.') ON CONFLICT (control_code) DO NOTHING;
INSERT INTO rc_controls (control_code, area, title_en, title_ar, requirement_en, control_type, type_codes, frequency, criticality, owner_role, linked_module, linked_params, licence_types, test_procedure_en) VALUES ('FRA-006', 'capital_licensing', 'Key functions filled and notified to FRA', 'شغل الوظائف الرئيسية وإخطار الهيئة بها', 'Key-functions register (role, holder, fit & proper, FRA notification date/reference, no-objection status); vacancy and "filled but not notified" alerts.', 'workflow', 'W/E', 'monthly', 'high', 'compliance_head', 'governance', '{}'::text[], ARRAY['all']::text[], 'Confirm that: key-functions register (role, holder, fit & proper, FRA notification date/reference, no-objection status); vacancy and "filled but not notified" alerts.') ON CONFLICT (control_code) DO NOTHING;
INSERT INTO rc_controls (control_code, area, title_en, title_ar, requirement_en, control_type, type_codes, frequency, criticality, owner_role, linked_module, linked_params, licence_types, test_procedure_en) VALUES ('FRA-007', 'capital_licensing', 'Branch manager appointed with FRA no-objection', 'تعيين مدير الفرع بعد عدم ممانعة الهيئة', 'Branch register with manager; FRA no-objection required before a branch is active; vacancy timer after a resignation.', 'workflow', 'W', 'monthly', 'high', 'operations_head', 'governance', ARRAY['branch.manager_vacancy_max_days']::text[], ARRAY['all']::text[], 'Confirm that: branch register with manager; FRA no-objection required before a branch is active; vacancy timer after a resignation.') ON CONFLICT (control_code) DO NOTHING;
