INSERT INTO rc_controls (control_code, area, title_en, title_ar, requirement_en, control_type, type_codes, frequency, criticality, owner_role, linked_module, linked_params, licence_types, test_procedure_en) VALUES ('FRA-014', 'origination', 'Client acknowledgement of receipt of funds', 'إقرار العميل باستلام مبلغ التمويل', 'Receipt acknowledgement is a required document before a loan is marked disbursed.', 'automated', 'A', 'daily', 'medium', 'operations_head', 'lending', '{}'::text[], ARRAY['microfinance', 'consumer_finance']::text[], 'Confirm that: receipt acknowledgement is a required document before a loan is marked disbursed.') ON CONFLICT (control_code) DO NOTHING;
